package com.billbookmanagement.modules.subjects.repository;
import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.Repository;import java.util.*;
@Repository public class AddressRepository{private final JdbcTemplate db;public AddressRepository(JdbcTemplate db){this.db=db;}public List<Map<String,Object>> list(long s){return db.queryForList("SELECT a.*,sa.address_type,sa.is_default,sa.valid_from,sa.valid_to FROM address a JOIN subject_address sa ON sa.address_id=a.id WHERE sa.subject_id=? ORDER BY sa.is_default DESC,a.id",s);}public void address(Object...v){db.update("INSERT INTO address(address_line1,address_line2,street_number,city,region,postal_code,country_code) VALUES(?,?,?,?,?,?,?)",v);}public long id(){return db.queryForObject("SELECT LAST_INSERT_ID()",Long.class);}public void link(Object...v){db.update("INSERT INTO subject_address(subject_id,address_id,address_type,is_default,valid_from,valid_to) VALUES(?,?,?,?,?,?)",v);}public Map<String,Object> one(long id){return db.queryForMap("SELECT a.*,sa.address_type,sa.is_default,sa.valid_from,sa.valid_to FROM address a JOIN subject_address sa ON sa.address_id=a.id WHERE a.id=?",id);}public void delete(long s,long a){db.update("DELETE FROM subject_address WHERE subject_id=? AND address_id=?",s,a);db.update("DELETE FROM address WHERE id=?",a);}}
